         <button type="button" onClick={() => signOut({ redirectUrl: basePath || '/' })} className="mt-4 flex w-full items-center gap-3 rounded-lg text-left hover:bg-sidebar-accent/70"><div className="flex h-8 w-8 items-center justify-center rounded-full bg-secondary font-mono text-xs font-bold text-sidebar-primary-foreground">{initials}</div><div className="min-w-0 flex-1"><div className="truncate text-xs font-semibold">{displayName}</div><div className="truncate text-[10px] text-sidebar-foreground/45">Sign out</div></div><MoreHorizontal size={16} className="text-sidebar-foreground/40" /></button>
