function PageIntro({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: React.ReactNode }) {
  return <div className="mb-7 flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><div className="mb-2 flex items-center gap-2 font-mono text-[10px] uppercase tracking-[.2em] text-primary"><span className="h-1.5 w-1.5 rounded-full bg-accent" />{eyebrow}</div><h1 className="font-display text-[32px] font-semibold tracking-[-.035em] text-foreground sm:text-[40px]">{title}</h1><p className="mt-2 max-w-2xl text-sm leading-relaxed text-muted-foreground">{description}</p></div>{action}</div>;
}
function MetricCard({ label, value, note, icon: Icon, accent = 'primary' }: { label: string; value: React.ReactNode; note: string; icon: typeof Activity; accent?: 'primary' | 'secondary' | 'accent' }) {
  return <div className="rounded-xl border border-border bg-card p-4 shadow-[0_1px_0_hsl(var(--foreground)/.04)] transition-transform hover:-translate-y-0.5 sm:p-5"><div className="flex items-start justify-between"><span className="font-mono text-[10px] uppercase tracking-[.13em] text-muted-foreground">{label}</span><div className={cn('rounded-lg p-2', accent === 'secondary' ? 'bg-secondary/20 text-primary' : accent === 'accent' ? 'bg-accent/10 text-accent' : 'bg-primary/10 text-primary')}><Icon size={16} /></div></div><div className="mt-4 font-display text-3xl font-semibold tracking-tight">{value}</div><div className="mt-1 flex items-center gap-1.5 text-[11px] text-muted-foreground"><TrendingUp size={12} className="text-accent" />{note}</div></div>;
}

function Overview() {
  const { user } = useUser();
  const firstName = user?.firstName ?? user?.fullName?.split(/\s+/)[0] ?? 'there';
  const summaryQuery = useGetDashboardSummary({ query: { queryKey: getGetDashboardSummaryQueryKey() } });
  const activityQuery = useListActivity({ query: { queryKey: getListActivityQueryKey() } });
  const summary = summaryQuery.data ?? { policyCount: 1248, schemeCount: 386, activeAlerts: 12, savedItems: 27, trend: [{ label: 'Jan', policies: 84, schemes: 50 }, { label: 'Feb', policies: 105, schemes: 72 }, { label: 'Mar', policies: 92, schemes: 88 }, { label: 'Apr', policies: 127, schemes: 96 }, { label: 'May', policies: 141, schemes: 112 }, { label: 'Jun', policies: 156, schemes: 138 }], coverage: [{ label: 'Health', value: 82 }, { label: 'Education', value: 67 }, { label: 'Agriculture', value: 54 }, { label: 'Housing', value: 43 }] };
  const activity = activityQuery.data ?? [{ id: 1, title: 'Clean Air Programme updated', description: 'Implementation guidelines for 12 cities are now available.', time: '18 min ago', type: 'policy' }, { id: 2, title: 'New scheme match found', description: 'Three schemes match your saved citizen profile.', time: '2 hr ago', type: 'match' }, { id: 3, title: 'Research brief exported', description: 'Water security comparison is ready to download.', time: 'Yesterday', type: 'report' }];
  const maxTrend = Math.max(...summary.trend.map((item) => Math.max(item.policies, item.schemes)), 1);
   return <><PageIntro eyebrow="Command center / live view" title={`Good morning, ${firstName}.`} description="A clear read of the public policy landscape, tailored to the things you follow." action={<Link href="/eligibility" data-testid="link-check-eligibility" className="inline-flex items-center gap-2 rounded-lg bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground shadow-sm transition-transform hover:-translate-y-0.5">Check eligibility <ArrowRight size={15} /></Link>} />
    <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><MetricCard label="Policies indexed" value={summary.policyCount.toLocaleString()} note="+8.4% this quarter" icon={BookOpen} /><MetricCard label="Public schemes" value={summary.schemeCount.toLocaleString()} note="+21 added this month" icon={Globe2} accent="accent" /><MetricCard label="Active alerts" value={summary.activeAlerts} note="2 need your attention" icon={Bell} accent="secondary" /><MetricCard label="Saved intelligence" value={summary.savedItems} note="Across 4 workspaces" icon={Bookmark} /></div>
    <div className="mt-5 grid gap-5 xl:grid-cols-[1.55fr_1fr]">
      <section className="rounded-xl border border-border bg-card p-5 sm:p-6"><div className="flex items-start justify-between"><div><div className="font-mono text-[10px] uppercase tracking-[.14em] text-muted-foreground">Knowledge graph / 6 months</div><h2 className="mt-1 font-display text-xl font-semibold">Policy activity is accelerating</h2></div><button data-testid="button-trend-filter" className="flex items-center gap-1.5 rounded-md border border-border px-2.5 py-1.5 text-[11px] font-semibold text-muted-foreground hover:bg-muted">Monthly <ChevronDown size={13} /></button></div><div className="mt-8 flex h-48 items-end gap-2 border-b border-border/80 pb-0 sm:gap-4">{summary.trend.map((item) => <div key={item.label} className="flex h-full flex-1 flex-col justify-end gap-2"><div className="flex h-full items-end justify-center gap-1.5"><div className="w-3 rounded-t bg-primary/80 transition-all hover:bg-primary sm:w-5" style={{ height: `${Math.max(7, item.policies / maxTrend * 100)}%` }} title={`${item.policies} policies`} /><div className="w-3 rounded-t bg-secondary transition-all hover:bg-secondary/80 sm:w-5" style={{ height: `${Math.max(7, item.schemes / maxTrend * 100)}%` }} title={`${item.schemes} schemes`} /></div><span className="font-mono text-[10px] text-muted-foreground">{item.label}</span></div>)}</div><div className="mt-4 flex gap-5 text-[11px] text-muted-foreground"><span className="flex items-center gap-2"><i className="h-2 w-2 rounded-full bg-primary" />Policies</span><span className="flex items-center gap-2"><i className="h-2 w-2 rounded-full bg-secondary" />Schemes</span><span className="ml-auto hidden font-mono sm:block">Source: PolicyGPT index</span></div></section>
      <section className="rounded-xl border border-border bg-card p-5 sm:p-6"><div className="flex items-start justify-between"><div><div className="font-mono text-[10px] uppercase tracking-[.14em] text-muted-foreground">Live stream</div><h2 className="mt-1 font-display text-xl font-semibold">Recent activity</h2></div><Link href="/reports" data-testid="link-view-activity" className="text-[11px] font-semibold text-primary hover:underline">View all</Link></div><div className="mt-5 space-y-1">{activity.slice(0, 4).map((item: any) => <div key={item.id} data-testid={`activity-item-${item.id}`} className="group flex gap-3 rounded-lg px-2 py-3 hover:bg-muted/60"><div className={cn('mt-1 flex h-7 w-7 shrink-0 items-center justify-center rounded-lg', item.type === 'match' ? 'bg-secondary/20 text-primary' : item.type === 'report' ? 'bg-accent/10 text-accent' : 'bg-primary/10 text-primary')}><Activity size={14} /></div><div className="min-w-0 flex-1"><div className="text-xs font-semibold">{item.title}</div><p className="mt-0.5 truncate text-[11px] text-muted-foreground">{item.description}</p></div><span className="whitespace-nowrap pt-0.5 font-mono text-[9px] text-muted-foreground/70">{item.time}</span></div>)}</div></section>
    </div>
    <div className="mt-5 grid gap-5 lg:grid-cols-[1fr_1fr_.85fr]">
      <section className="rounded-xl border border-border bg-card p-5"><div className="mb-5 flex items-center justify-between"><div><div className="font-mono text-[10px] uppercase tracking-[.14em] text-muted-foreground">Coverage map</div><h2 className="mt-1 font-display text-lg font-semibold">Where attention is focused</h2></div><MapPin size={18} className="text-accent" /></div><div className="space-y-4">{summary.coverage.map((point) => <div key={point.label}><div className="mb-1.5 flex justify-between text-xs"><span className="font-medium">{point.label}</span><span className="font-mono text-muted-foreground">{point.value}%</span></div><div className="h-2 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-primary transition-all" style={{ width: `${point.value}%` }} /></div></div>)}</div></section>
      <section className="dot-grid rounded-xl border border-primary/10 bg-primary/5 p-5"><div className="flex items-center gap-2 text-primary"><Zap size={17} /><span className="font-mono text-[10px] uppercase tracking-[.15em]">Quick actions</span></div><h2 className="mt-2 font-display text-xl font-semibold">Turn a question into a lead.</h2><div className="mt-5 grid gap-2">{[{ href: '/policies', label: 'Search policy repository', icon: Search }, { href: '/schemes', label: 'Find public schemes', icon: Globe2 }, { href: '/compare', label: 'Compare two records', icon: SlidersHorizontal }].map(({ href, label, icon: Icon }) => <Link key={href} href={href} data-testid={`link-quick-${label.toLowerCase().replaceAll(' ', '-')}`} className="flex items-center gap-3 rounded-lg border border-border/80 bg-card/80 px-3 py-2.5 text-xs font-semibold transition-colors hover:border-primary/30 hover:bg-card"><Icon size={15} className="text-primary" />{label}<ArrowRight size={14} className="ml-auto text-muted-foreground" /></Link>)}</div></section>
      <section className="rounded-xl border border-border bg-card p-5"><div className="flex items-center justify-between"><div><div className="font-mono text-[10px] uppercase tracking-[.14em] text-muted-foreground">Attention queue</div><h2 className="mt-1 font-display text-lg font-semibold">12 active alerts</h2></div><AlertCircle size={18} className="text-destructive" /></div><div className="mt-5 space-y-3"><div className="border-l-2 border-destructive pl-3"><div className="text-xs font-semibold">2 policy statuses changed</div><div className="mt-1 text-[11px] text-muted-foreground">Since your last visit</div></div><div className="border-l-2 border-secondary pl-3"><div className="text-xs font-semibold">5 deadlines in next 30 days</div><div className="mt-1 text-[11px] text-muted-foreground">Across saved schemes</div></div><div className="border-l-2 border-accent pl-3"><div className="text-xs font-semibold">New coverage in Bihar</div><div className="mt-1 text-[11px] text-muted-foreground">8 records added today</div></div></div><Link href="/notifications" data-testid="link-open-alerts" className="mt-5 inline-flex items-center gap-1.5 text-[11px] font-semibold text-primary hover:underline">Open alert center <ArrowRight size={13} /></Link></section>
    </div>
  </>;
}

function SearchBar({ value, onChange, placeholder }: { value: string; onChange: (value: string) => void; placeholder: string }) {
  return <div className="relative flex-1"><Search size={17} className="pointer-events-none absolute left-3.5 top-1/2 -translate-y-1/2 text-muted-foreground" /><input data-testid="input-search" value={value} onChange={(event) => onChange(event.target.value)} placeholder={placeholder} className="focus-ring h-11 w-full rounded-lg border border-border bg-card pl-10 pr-10 text-sm outline-none placeholder:text-muted-foreground/70 focus:border-primary/50" />{value && <button data-testid="button-clear-search" onClick={() => onChange('')} className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"><X size={15} /></button>}</div>;
}
function Policies() {
  const [search, setSearch] = useState(''); const [category, setCategory] = useState('All categories'); const [status, setStatus] = useState('All statuses'); const [showCreate, setShowCreate] = useState(false);
  const params = useMemo(() => ({ query: search || undefined, category: category === 'All categories' ? undefined : category, status: status === 'All statuses' ? undefined : status, limit: 50 }), [search, category, status]);
  const query = useListPolicies(params, { query: { queryKey: getListPoliciesQueryKey(params) } }); const createPolicy = useCreatePolicy();
  const [form, setForm] = useState({ title: '', category: 'Environment', ministry: '', state: 'National', summary: '' });
  const data = query.data ?? fallbackPolicies; const categories = ['All categories', 'Environment', 'Technology', 'Water', 'Education', 'Health', 'Agriculture'];
  const submit = (event: React.FormEvent) => { event.preventDefault(); createPolicy.mutate({ data: { ...form, tags: [] } }, { onSuccess: () => { setShowCreate(false); setForm({ title: '', category: 'Environment', ministry: '', state: 'National', summary: '' }); queryClient.invalidateQueries({ queryKey: getListPoliciesQueryKey(params) }); } }); };
  return <><PageIntro eyebrow="Repository / indexed records" title="Policy repository" description="Search the decisions, frameworks and programmes shaping public life. Every record carries its source context and current status." action={<button data-testid="button-create-policy" onClick={() => setShowCreate(true)} className="inline-flex items-center gap-2 rounded-lg bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground hover:-translate-y-0.5"><Plus size={16} /> Add policy</button>} />
    <div className="mb-5 flex flex-col gap-3 rounded-xl border border-border bg-card p-3 sm:flex-row"><SearchBar value={search} onChange={setSearch} placeholder="Search by title, ministry, topic or tag" /><div className="flex gap-2 overflow-x-auto"><select data-testid="select-category" value={category} onChange={(e) => setCategory(e.target.value)} className="h-11 min-w-[155px] rounded-lg border border-border bg-card px-3 text-xs font-medium outline-none"><option>{categories[0]}</option>{categories.slice(1).map((c) => <option key={c}>{c}</option>)}</select><select data-testid="select-status" value={status} onChange={(e) => setStatus(e.target.value)} className="h-11 min-w-[135px] rounded-lg border border-border bg-card px-3 text-xs font-medium outline-none"><option>All statuses</option><option>Active</option><option>Under review</option><option>Archived</option></select><button data-testid="button-more-filters" className="flex h-11 items-center gap-2 rounded-lg border border-border px-3 text-xs font-semibold text-muted-foreground hover:bg-muted"><Filter size={14} /> <span className="hidden sm:inline">More</span></button></div></div>
    <div className="mb-4 flex items-center justify-between text-xs text-muted-foreground"><span><strong className="text-foreground">{data.length}</strong> records surfaced</span><button data-testid="button-sort-policies" className="flex items-center gap-1.5 font-semibold hover:text-foreground"><ListFilter size={14} /> Recently updated <ChevronDown size={13} /></button></div>
    {query.isError ? <ErrorState retry={() => query.refetch()} /> : <div className="space-y-3">{data.length === 0 ? <EmptyState icon={Search} title="No policies found" description="Try a broader search or remove one of the filters." action={<button data-testid="button-reset-policy-filters" onClick={() => { setSearch(''); setCategory('All categories'); setStatus('All statuses'); }} className="text-sm font-semibold text-primary hover:underline">Reset filters</button>} /> : data.map((policy: any) => <PolicyRow key={policy.id} policy={policy} />)}</div>}
    {showCreate && <Modal title="Add a policy record" onClose={() => setShowCreate(false)}><form onSubmit={submit} className="space-y-4">{[['title', 'Policy title'], ['ministry', 'Ministry / department'], ['summary', 'Short summary']].map(([key, label]) => <label key={key} className="block text-xs font-semibold">{label}{key === 'summary' ? <textarea data-testid={`input-policy-${key}`} required rows={3} value={(form as any)[key]} onChange={(e) => setForm({ ...form, [key]: e.target.value })} className="mt-1.5 w-full rounded-lg border border-border bg-background p-3 text-sm outline-none focus:border-primary" /> : <input data-testid={`input-policy-${key}`} required value={(form as any)[key]} onChange={(e) => setForm({ ...form, [key]: e.target.value })} className="mt-1.5 h-10 w-full rounded-lg border border-border bg-background px-3 text-sm outline-none focus:border-primary" />}</label>)}<label className="block text-xs font-semibold">Category<select data-testid="select-policy-category" value={form.category} onChange={(e) => setForm({ ...form, category: e.target.value })} className="mt-1.5 h-10 w-full rounded-lg border border-border bg-background px-3 text-sm"><option>Environment</option><option>Technology</option><option>Education</option><option>Health</option></select></label><div className="flex justify-end gap-2 pt-2"><button type="button" data-testid="button-cancel-policy" onClick={() => setShowCreate(false)} className="rounded-lg px-4 py-2 text-sm font-semibold text-muted-foreground hover:bg-muted">Cancel</button><button type="submit" data-testid="button-submit-policy" disabled={createPolicy.isPending} className="inline-flex items-center gap-2 rounded-lg bg-primary px-4 py-2 text-sm font-semibold text-primary-foreground disabled:opacity-60">{createPolicy.isPending && <Loader2 size={14} className="animate-spin" />}Publish record</button></div></form></Modal>}
  </>;
}
function PolicyRow({ policy }: { policy: any }) { return <Link href={`/policies/${policy.id}`} data-testid={`card-policy-${policy.id}`} className="group block rounded-xl border border-border bg-card p-4 transition-all hover:-translate-y-0.5 hover:border-primary/30 hover:shadow-[0_8px_24px_hsl(var(--primary)/.07)] sm:p-5"><div className="flex flex-col gap-4 sm:flex-row sm:items-start"><div className="flex min-w-0 flex-1 gap-3"><div className="mt-0.5 hidden h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-primary/8 text-primary sm:flex"><FileText size={17} /></div><div className="min-w-0"><div className="mb-1.5 flex flex-wrap items-center gap-2"><span className="font-mono text-[10px] uppercase tracking-wide text-muted-foreground">{policy.category}</span><span className="text-border">/</span><span className="font-mono text-[10px] text-muted-foreground">{policy.state}</span></div><h3 className="font-display text-lg font-semibold tracking-tight group-hover:text-primary">{policy.title}</h3><p className="mt-1.5 line-clamp-2 max-w-3xl text-sm leading-relaxed text-muted-foreground">{policy.summary}</p><div className="mt-3 flex flex-wrap gap-1.5">{(policy.tags ?? []).slice(0, 3).map((tag: string) => <span key={tag} className="rounded-md bg-muted px-2 py-1 font-mono text-[10px] text-muted-foreground">#{tag}</span>)}</div></div></div><div className="flex shrink-0 items-center justify-between gap-4 sm:flex-col sm:items-end"><StatusPill tone={policy.status === 'Active' ? 'teal' : policy.status === 'Archived' ? 'slate' : 'amber'}>{policy.status}</StatusPill><span className="font-mono text-[10px] text-muted-foreground">{formatDate(policy.publishedDate)}</span></div></div></Link>; }

function Modal({ title, onClose, children }: { title: string; onClose: () => void; children: React.ReactNode }) { return <div className="fixed inset-0 z-50 flex items-end justify-center bg-primary/30 p-0 backdrop-blur-sm sm:items-center sm:p-6"><div className="max-h-[90dvh] w-full max-w-lg overflow-y-auto rounded-t-2xl border border-border bg-card p-5 shadow-2xl sm:rounded-2xl sm:p-6"><div className="mb-5 flex items-center justify-between"><h2 className="font-display text-xl font-semibold">{title}</h2><button data-testid="button-close-modal" onClick={onClose} className="rounded-lg p-2 text-muted-foreground hover:bg-muted"><X size={17} /></button></div>{children}</div></div>; }

function PolicyDetail() { const { id } = useParams<{ id: string }>(); const policyId = Number(id); const query = useGetPolicy(policyId, { query: { enabled: !!policyId, queryKey: getGetPolicyQueryKey(policyId) } }); const update = useUpdatePolicy(); const [notice, setNotice] = useState(''); const policy: any = query.data ?? fallbackPolicies.find((item) => item.id === policyId) ?? fallbackPolicies[0]; const change = (status: string) => update.mutate({ id: policyId, data: { status } }, { onSuccess: () => setNotice(`Record marked ${status.toLowerCase()}.`) }); return <>{query.isError && <ErrorState retry={() => query.refetch()} />}<div className="mb-5"><Link href="/policies" data-testid="link-back-policies" className="inline-flex items-center gap-1.5 text-xs font-semibold text-muted-foreground hover:text-primary">← Back to repository</Link></div><div className="grid gap-5 xl:grid-cols-[1fr_330px]"><div><div className="rounded-xl border border-border bg-card p-5 sm:p-8"><div className="flex flex-wrap items-center gap-2"><span className="font-mono text-[10px] uppercase tracking-[.15em] text-primary">{policy.category}</span><span className="text-border">/</span><span className="font-mono text-[10px] text-muted-foreground">{policy.state}</span><StatusPill tone={policy.status === 'Active' ? 'teal' : 'amber'}>{policy.status}</StatusPill></div><h1 className="mt-5 max-w-3xl font-display text-3xl font-semibold tracking-[-.04em] sm:text-5xl">{policy.title}</h1><p className="mt-5 max-w-3xl text-base leading-8 text-muted-foreground">{policy.summary}</p><div className="mt-8 grid gap-4 border-y border-border py-5 sm:grid-cols-3"><div><div className="font-mono text-[9px] uppercase tracking-wider text-muted-foreground">Owning ministry</div><div className="mt-1 text-sm font-semibold">{policy.ministry}</div></div><div><div className="font-mono text-[9px] uppercase tracking-wider text-muted-foreground">Published</div><div className="mt-1 text-sm font-semibold">{formatDate(policy.publishedDate)}</div></div><div><div className="font-mono text-[9px] uppercase tracking-wider text-muted-foreground">Expected impact</div><div className="mt-1 text-sm font-semibold text-accent">{policy.impact ?? 'Moderate'}</div></div></div><h2 className="mt-8 font-display text-xl font-semibold">What this means</h2><p className="mt-3 text-sm leading-7 text-muted-foreground">This record is part of the PolicyGPT public index. Read the original notification alongside this summary before making a decision. The context layer tracks scope, implementation signals and changes over time.</p><div className="mt-6 flex flex-wrap gap-2">{(policy.tags ?? []).map((tag: string) => <span key={tag} className="rounded-md border border-border px-2.5 py-1.5 font-mono text-[10px] text-muted-foreground">#{tag}</span>)}</div></div></div><aside className="space-y-5"><div className="rounded-xl border border-border bg-card p-5"><div className="flex items-center gap-2 text-primary"><Flag size={16} /><span className="font-mono text-[10px] uppercase tracking-[.14em]">Status control</span></div><p className="mt-3 text-xs leading-relaxed text-muted-foreground">For officials and reviewers. Update the lifecycle marker when the record changes.</p><div className="mt-4 space-y-2"><button data-testid="button-status-active" onClick={() => change('Active')} className="flex w-full items-center justify-between rounded-lg border border-border px-3 py-2.5 text-xs font-semibold hover:border-accent hover:bg-accent/5">Mark active <Check size={14} className="text-accent" /></button><button data-testid="button-status-review" onClick={() => change('Under review')} className="flex w-full items-center justify-between rounded-lg border border-border px-3 py-2.5 text-xs font-semibold hover:border-secondary hover:bg-secondary/10">Send to review <Clock3 size={14} className="text-primary" /></button><button data-testid="button-status-archive" onClick={() => change('Archived')} className="flex w-full items-center justify-between rounded-lg border border-border px-3 py-2.5 text-xs font-semibold hover:border-destructive hover:bg-destructive/5">Archive record <LockKeyhole size={14} className="text-destructive" /></button></div>{notice && <div className="mt-3 rounded-lg bg-accent/10 p-2.5 text-[11px] text-accent">{notice}</div>}</div><div className="rounded-xl border border-border bg-primary p-5 text-primary-foreground"><Sparkles size={18} className="text-secondary" /><h3 className="mt-3 font-display text-lg font-semibold">Build a brief</h3><p className="mt-1 text-xs leading-relaxed text-primary-foreground/65">Compare this record with related policies and export a research-ready view.</p><Link href="/compare" data-testid="link-compare-policy" className="mt-4 inline-flex items-center gap-2 rounded-lg bg-secondary px-3 py-2 text-xs font-bold text-secondary-foreground">Add to compare <ArrowRight size={14} /></Link></div></aside></div></>; }

function Schemes() { const [search, setSearch] = useState(''); const [category, setCategory] = useState('All categories'); const params = useMemo(() => ({ query: search || undefined, category: category === 'All categories' ? undefined : category, limit: 50 }), [search, category]); const query = useListSchemes(params, { query: { queryKey: getListSchemesQueryKey(params) } }); const data = query.data ?? fallbackSchemes; return <><PageIntro eyebrow="Citizen services / discovery" title="Find a scheme that fits." description="A practical index of public benefits. Search the programme, then understand what you need before you apply." action={<Link href="/eligibility" data-testid="link-scheme-eligibility" className="inline-flex items-center gap-2 rounded-lg border border-primary px-4 py-2.5 text-sm font-semibold text-primary hover:bg-primary/5"><ClipboardCheck size={16} /> Match my profile</Link>} /><div className="mb-6 flex flex-col gap-3 rounded-xl border border-border bg-card p-3 sm:flex-row"><SearchBar value={search} onChange={setSearch} placeholder="Search benefits, communities or departments" /><select data-testid="select-scheme-category" value={category} onChange={(e) => setCategory(e.target.value)} className="h-11 min-w-[170px] rounded-lg border border-border bg-card px-3 text-xs font-medium"><option>All categories</option><option>Health</option><option>Agriculture</option><option>Education</option><option>Housing</option></select></div>{query.isError ? <ErrorState retry={() => query.refetch()} /> : data.length === 0 ? <EmptyState icon={Globe2} title="No schemes match yet" description="Try searching for a benefit, community or ministry." /> : <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{data.map((scheme: any, index: number) => <SchemeCard key={scheme.id} scheme={scheme} featured={index === 0} />)}</div>}</>; }
function SchemeCard({ scheme, featured }: { scheme: any; featured?: boolean }) { return <Link href={`/schemes/${scheme.id}`} data-testid={`card-scheme-${scheme.id}`} className={cn('group relative flex flex-col rounded-xl border bg-card p-5 transition-all hover:-translate-y-1 hover:shadow-[0_12px_28px_hsl(var(--primary)/.08)]', featured ? 'border-primary/30' : 'border-border')}><div className="flex items-start justify-between"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-secondary/25 text-primary"><Globe2 size={19} /></div><span aria-label="Saved scheme" className="rounded-lg p-2 text-muted-foreground"><Bookmark size={16} /></span></div><div className="mt-5 flex items-center gap-2 font-mono text-[10px] uppercase tracking-wide text-muted-foreground"><span>{scheme.category}</span><span className="text-border">/</span><span>{scheme.state}</span></div><h3 className="mt-2 font-display text-xl font-semibold tracking-tight group-hover:text-primary">{scheme.name}</h3><p className="mt-2 line-clamp-2 text-sm leading-relaxed text-muted-foreground">{scheme.description}</p><div className="mt-5 border-t border-border pt-4"><div className="font-mono text-[9px] uppercase tracking-wider text-muted-foreground">Primary benefit</div><div className="mt-1 text-sm font-semibold">{scheme.benefit}</div></div><div className="mt-5 flex items-center justify-between text-[11px]"><span className="flex items-center gap-1.5 text-muted-foreground"><Users size={13} />{scheme.beneficiaries}</span><span className="font-semibold text-primary">View scheme <ArrowRight size={13} className="ml-1 inline transition-transform group-hover:translate-x-1" /></span></div></Link>; }

function SchemeDetail() { const { id } = useParams<{ id: string }>(); const schemeId = Number(id); const query = useGetScheme(schemeId, { query: { enabled: !!schemeId, queryKey: getGetSchemeQueryKey(schemeId) } }); const scheme: any = query.data ?? fallbackSchemes.find((item) => item.id === schemeId) ?? fallbackSchemes[0]; return <>{query.isError && <ErrorState retry={() => query.refetch()} />}<div className="mb-5"><Link href="/schemes" data-testid="link-back-schemes" className="inline-flex items-center gap-1.5 text-xs font-semibold text-muted-foreground hover:text-primary">← Back to scheme finder</Link></div><div className="grid gap-5 xl:grid-cols-[1fr_370px]"><div><div className="rounded-xl border border-border bg-card p-5 sm:p-8"><div className="flex flex-wrap items-center gap-2 font-mono text-[10px] uppercase tracking-[.15em] text-primary"><span>{scheme.category}</span><span className="text-border">/</span><span className="text-muted-foreground">{scheme.state}</span></div><h1 className="mt-5 font-display text-3xl font-semibold tracking-[-.04em] sm:text-5xl">{scheme.name}</h1><p className="mt-5 max-w-2xl text-base leading-8 text-muted-foreground">{scheme.description}</p><div className="mt-8 rounded-xl bg-primary p-5 text-primary-foreground"><div className="font-mono text-[10px] uppercase tracking-wider text-primary-foreground/55">What you could receive</div><div className="mt-2 font-display text-2xl font-semibold">{scheme.benefit}</div><div className="mt-2 text-xs text-primary-foreground/60">For {scheme.beneficiaries}</div></div><h2 className="mt-8 font-display text-xl font-semibold">Eligibility signals</h2><div className="mt-4 space-y-2.5">{(scheme.eligibility ?? []).map((item: string, index: number) => <div key={item} className="flex items-start gap-3 rounded-lg border border-border p-3 text-sm"><span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-accent/15 font-mono text-[10px] font-bold text-accent">{index + 1}</span><span>{item}</span></div>)}</div></div></div><aside className="space-y-5"><div className="rounded-xl border border-border bg-card p-5"><div className="flex items-center justify-between"><span className="font-mono text-[10px] uppercase tracking-[.14em] text-muted-foreground">How to apply</span><Send size={16} className="text-accent" /></div><div className="mt-5 space-y-0">{(scheme.steps ?? []).map((step: string, index: number) => <div key={step} className="relative flex gap-3 pb-5 last:pb-0"><div className="relative z-10 flex h-7 w-7 shrink-0 items-center justify-center rounded-full border border-primary bg-card font-mono text-[10px] font-bold text-primary">{index + 1}</div>{index < scheme.steps.length - 1 && <div className="absolute left-3.5 top-7 h-full w-px bg-border" />}<p className="pt-1 text-xs leading-relaxed">{step}</p></div>)}</div><button data-testid="button-start-application" onClick={() => window.alert('Application guidance saved to your workspace.')} className="mt-5 flex w-full items-center justify-center gap-2 rounded-lg bg-secondary py-2.5 text-xs font-bold text-secondary-foreground hover:brightness-95">Start application guide <ArrowRight size={14} /></button></div><div className="rounded-xl border border-secondary/40 bg-secondary/10 p-5"><div className="flex items-center gap-2 text-primary"><Clock3 size={16} /><span className="font-mono text-[10px] uppercase tracking-wider">Deadline</span></div><div className="mt-2 font-display text-lg font-semibold">{scheme.deadline}</div><p className="mt-1 text-xs text-muted-foreground">Confirm dates on the official portal before applying.</p></div></aside></div></>; }

 function Eligibility() { const check = useCheckEligibility(); const [input, setInput] = useState({ age: '28', income: '360000', occupation: 'Self-employed', education: 'Graduate', location: 'Maharashtra', socialCategory: 'General', disability: false }); const [result, setResult] = useState<any>(null); const submit = (event: React.FormEvent) => { event.preventDefault(); check.mutate({ data: { ...input, age: Number(input.age), income: Number(input.income) } }, { onSuccess: setResult }); }; return <><PageIntro eyebrow="Access / profile match" title="Check what you may qualify for." description="Answer seven quick questions. We will surface relevant public schemes without storing sensitive profile details." /><div className="grid gap-5 xl:grid-cols-[420px_1fr]"><form onSubmit={submit} className="rounded-xl border border-border bg-card p-5 sm:p-6"><div className="mb-5 flex items-center gap-2"><div className="flex h-8 w-8 items-center justify-center rounded-lg bg-primary text-primary-foreground"><ClipboardCheck size={16} /></div><div><h2 className="text-sm font-semibold">Your profile</h2><p className="text-[11px] text-muted-foreground">Used only for this match</p></div></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-1">{[['age', 'Age', 'number'], ['income', 'Annual household income (₹)', 'number']].map(([key, label, type]) => <label key={key} className="text-xs font-semibold">{label}<input data-testid={`input-eligibility-${key}`} required type={type} value={(input as any)[key]} onChange={(e) => setInput({ ...input, [key]: e.target.value })} className="mt-1.5 h-10 w-full rounded-lg border border-border bg-background px-3 text-sm outline-none focus:border-primary" /></label>)}{[['occupation', 'Occupation', ['Self-employed', 'Salaried', 'Student', 'Farmer', 'Unemployed']], ['education', 'Education', ['School', 'Graduate', 'Postgraduate', 'No formal education']], ['location', 'State / location', ['Maharashtra', 'Rajasthan', 'Bihar', 'Delhi', 'Karnataka']], ['socialCategory', 'Social category', ['General', 'OBC', 'SC', 'ST']]].map(([key, label, options]) => <label key={String(key)} className="text-xs font-semibold">{label}<select data-testid={`select-eligibility-${String(key)}`} value={(input as any)[String(key)]} onChange={(e) => setInput({ ...input, [String(key)]: e.target.value })} className="mt-1.5 h-10 w-full rounded-lg border border-border bg-background px-3 text-sm">{(options as string[]).map((option) => <option key={option}>{option}</option>)}</select></label>)}</div><label className="mt-4 flex cursor-pointer items-center gap-2 text-xs font-medium"><input data-testid="checkbox-eligibility-disability" type="checkbox" checked={input.disability} onChange={(e) => setInput({ ...input, disability: e.target.checked })} className="h-4 w-4 accent-[hsl(var(--primary))]" />Person with disability</label><button data-testid="button-check-eligibility" disabled={check.isPending} className="mt-6 flex w-full items-center justify-center gap-2 rounded-lg bg-primary py-3 text-sm font-semibold text-primary-foreground disabled:opacity-60">{check.isPending ? <Loader2 size={16} className="animate-spin" /> : <Sparkles size={16} />}Find my matches</button><div className="mt-4 flex items-start gap-2 text-[10px] leading-relaxed text-muted-foreground"><LockKeyhole size={13} className="mt-0.5 shrink-0" />Your answers are sent securely to calculate matches and are not shown publicly.</div></form><div className="min-h-[500px]">{check.isError ? <ErrorState retry={() => setResult(null)} /> : result ? <div className="space-y-4"><div className="rounded-xl border border-accent/25 bg-accent/8 p-5"><div className="flex items-center gap-2 text-accent"><Check size={17} /><span className="font-mono text-[10px] uppercase tracking-wider">Match complete</span></div><div className="mt-2 font-display text-3xl font-semibold">{result.matchCount} schemes may fit</div><p className="mt-2 text-sm text-muted-foreground">{result.summary}</p></div><div className="space-y-3">{(result.recommended ?? []).map((scheme: any) => <SchemeCard key={scheme.id} scheme={scheme} />)}</div></div> : <div className="h-full rounded-xl border border-dashed border-border bg-card/40 p-6"><div className="flex h-full min-h-[420px] flex-col items-center justify-center text-center"><div className="mb-4 flex h-16 w-16 items-center justify-center rounded-2xl bg-secondary/20 text-primary"><Sparkles size={26} /></div><h2 className="font-display text-2xl font-semibold">Your matched schemes will appear here</h2><p className="mt-2 max-w-sm text-sm leading-relaxed text-muted-foreground">Complete the profile to replace guesswork with a considered starting point.</p><div className="mt-8 grid grid-cols-3 gap-3 text-center"><div><div className="font-display text-xl font-semibold">01</div><div className="mt-1 text-[10px] text-muted-foreground">Answer</div></div><div><div className="font-display text-xl font-semibold">02</div><div className="mt-1 text-[10px] text-muted-foreground">Match</div></div><div><div className="font-display text-xl font-semibold">03</div><div className="mt-1 text-[10px] text-muted-foreground">Act</div></div></div></div></div>}</div></div></>; }

function Compare() { const policiesQuery = useListPolicies({ limit: 50 }, { query: { queryKey: getListPoliciesQueryKey({ limit: 50 }) } }); const schemesQuery = useListSchemes({ limit: 50 }, { query: { queryKey: getListSchemesQueryKey({ limit: 50 }) } }); const [left, setLeft] = useState('National Clean Air Programme'); const [right, setRight] = useState('Digital Public Infrastructure Framework'); const records = [...(policiesQuery.data ?? fallbackPolicies), ...(schemesQuery.data ?? fallbackSchemes).map((s: any) => ({ ...s, title: s.name, summary: s.description, category: s.category, ministry: s.ministry, status: 'Scheme' }))] as any[]; const a = records.find((r) => (r.title ?? r.name) === left) ?? records[0]; const b = records.find((r) => (r.title ?? r.name) === right) ?? records[1]; return <><PageIntro eyebrow="Analysis / side by side" title="Compare with clarity." description="Put two records next to each other. Notice the difference in scope, ownership and practical reach." action={<button data-testid="button-export-comparison" onClick={() => window.print()} className="inline-flex items-center gap-2 rounded-lg border border-border px-4 py-2.5 text-sm font-semibold hover:bg-muted"><Download size={16} /> Export view</button>} /><div className="mb-5 grid gap-3 rounded-xl border border-border bg-card p-4 sm:grid-cols-2"><label className="text-xs font-semibold">Record A<select data-testid="select-compare-left" value={left} onChange={(e) => setLeft(e.target.value)} className="mt-1.5 h-11 w-full rounded-lg border border-border bg-background px-3 text-sm">{records.slice(0, 30).map((r) => <option key={`a-${r.id}-${r.title}`}>{r.title ?? r.name}</option>)}</select></label><label className="text-xs font-semibold">Record B<select data-testid="select-compare-right" value={right} onChange={(e) => setRight(e.target.value)} className="mt-1.5 h-11 w-full rounded-lg border border-border bg-background px-3 text-sm">{records.slice(0, 30).map((r) => <option key={`b-${r.id}-${r.title}`}>{r.title ?? r.name}</option>)}</select></label></div><div className="overflow-hidden rounded-xl border border-border bg-card"><div className="grid grid-cols-2 border-b border-border bg-muted/50"><div className="border-r border-border p-5 sm:p-6"><div className="font-mono text-[9px] uppercase tracking-wider text-primary">Record A</div><h2 className="mt-2 font-display text-xl font-semibold">{a?.title ?? 'Select a record'}</h2></div><div className="p-5 sm:p-6"><div className="font-mono text-[9px] uppercase tracking-wider text-accent">Record B</div><h2 className="mt-2 font-display text-xl font-semibold">{b?.title ?? 'Select a record'}</h2></div></div>{[['Category', 'category'], ['Ministry', 'ministry'], ['State / reach', 'state'], ['Status', 'status'], ['Summary', 'summary'], ['Benefit / impact', 'benefit']].map(([label, key]) => <div key={key} className="grid grid-cols-2 border-b border-border last:border-b-0"><div className="border-r border-border p-4 sm:p-5"><div className="mb-1 font-mono text-[9px] uppercase tracking-wider text-muted-foreground">{label}</div><div className="text-sm leading-relaxed">{a?.[key] ?? a?.impact ?? '—'}</div></div><div className="p-4 sm:p-5"><div className="mb-1 font-mono text-[9px] uppercase tracking-wider text-muted-foreground">{label}</div><div className="text-sm leading-relaxed">{b?.[key] ?? b?.impact ?? '—'}</div></div></div>)}</div></>; }

function Notifications() { const query = useListNotifications({ query: { queryKey: getListNotificationsQueryKey() } }); const mark = useMarkNotificationRead(); const [localRead, setLocalRead] = useState<number[]>([]); const items = query.data ?? [{ id: 1, title: 'Policy status changed', message: 'National Clean Air Programme moved to Active.', time: '18 min ago', read: false, type: 'policy' }, { id: 2, title: 'A new scheme matches you', message: 'National Scholarship Portal is relevant to your saved profile.', time: '2 hours ago', read: false, type: 'match' }, { id: 3, title: 'Report export ready', message: 'Your water security comparison is ready to download.', time: 'Yesterday', read: true, type: 'report' }]; const unread = items.filter((item: any) => !item.read && !localRead.includes(item.id)).length; return <><PageIntro eyebrow="Account / notification center" title="Stay in the loop." description="Changes to saved policies, new scheme matches and reports that are ready when you are." action={<button data-testid="button-mark-all-read" onClick={() => setLocalRead(items.map((i: any) => i.id))} className="rounded-lg border border-border px-4 py-2.5 text-xs font-semibold hover:bg-muted">Mark all as read</button>} /><div className="mb-4 flex items-center gap-3 text-xs text-muted-foreground"><span className="font-semibold text-foreground">{unread} unread</span><span className="text-border">/</span><span>{items.length} total updates</span></div><div className="space-y-2">{items.map((item: any) => { const isRead = item.read || localRead.includes(item.id); return <div key={item.id} data-testid={`notification-${item.id}`} className={cn('flex gap-4 rounded-xl border p-4 transition-colors sm:p-5', isRead ? 'border-border bg-card' : 'border-primary/15 bg-primary/5')}><div className={cn('mt-0.5 flex h-9 w-9 shrink-0 items-center justify-center rounded-lg', item.type === 'match' ? 'bg-secondary/20 text-primary' : item.type === 'report' ? 'bg-accent/10 text-accent' : 'bg-primary/10 text-primary')}><Bell size={16} /></div><div className="min-w-0 flex-1"><div className="flex flex-col justify-between gap-1 sm:flex-row"><h3 className="text-sm font-semibold">{item.title}</h3><span className="font-mono text-[10px] text-muted-foreground">{item.time}</span></div><p className="mt-1 text-sm leading-relaxed text-muted-foreground">{item.message}</p>{!isRead && <button data-testid={`button-read-notification-${item.id}`} onClick={() => { setLocalRead((prev) => [...prev, item.id]); mark.mutate({ id: item.id }); }} className="mt-3 text-[11px] font-semibold text-primary hover:underline">Mark as read</button>}</div>{!isRead && <span className="mt-2 h-2 w-2 shrink-0 rounded-full bg-destructive" />}</div>; })}</div></>; }

function Reports() { const [exported, setExported] = useState(false); return <><PageIntro eyebrow="Analysis / evidence pack" title="Reports, ready to carry." description="Turn your working set into a clean, export-ready brief for a meeting, newsroom or field team." action={<button data-testid="button-export-report" onClick={() => { setExported(true); window.print(); }} className="inline-flex items-center gap-2 rounded-lg bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground"><Download size={16} /> Export report</button>} />{exported && <div className="mb-5 flex items-center gap-2 rounded-lg border border-accent/20 bg-accent/10 p-3 text-xs text-accent"><Check size={15} /> Report prepared for print. Your browser's save dialog can create a PDF.</div>}<div className="grid gap-5 lg:grid-cols-[1.2fr_.8fr]"><div className="rounded-xl border border-border bg-card p-5 sm:p-6"><div className="flex items-center justify-between"><div><div className="font-mono text-[10px] uppercase tracking-wider text-muted-foreground">Portfolio pulse</div><h2 className="mt-1 font-display text-xl font-semibold">Your intelligence footprint</h2></div><BarChart3 size={19} className="text-primary" /></div><div className="mt-8 flex h-56 items-end gap-2 border-b border-border sm:gap-5">{[48, 62, 44, 77, 58, 84, 71, 92, 67, 81, 74, 96].map((height, i) => <div key={i} className="group flex flex-1 flex-col items-center gap-2"><div className="w-full max-w-8 rounded-t bg-primary/75 transition-all group-hover:bg-primary" style={{ height: `${height}%` }} /><span className="font-mono text-[9px] text-muted-foreground">{['J','F','M','A','M','J','J','A','S','O','N','D'][i]}</span></div>)}</div><div className="mt-5 grid grid-cols-3 gap-3"><div><div className="font-display text-2xl font-semibold">27</div><div className="text-[10px] text-muted-foreground">saved records</div></div><div><div className="font-display text-2xl font-semibold">11</div><div className="text-[10px] text-muted-foreground">briefs created</div></div><div><div className="font-display text-2xl font-semibold">4.8h</div><div className="text-[10px] text-muted-foreground">time saved</div></div></div></div><div className="space-y-5"><div className="rounded-xl border border-border bg-card p-5"><div className="font-mono text-[10px] uppercase tracking-wider text-muted-foreground">Suggested outputs</div><div className="mt-4 space-y-2">{[['Policy watchlist', '12 records · updated today', FileText], ['Scheme access brief', '8 matches · citizen profile', ClipboardCheck], ['State comparison', 'Maharashtra · Rajasthan', SlidersHorizontal]].map(([title, meta, Icon]) => <button key={title as string} data-testid={`button-report-${title}`} className="flex w-full items-center gap-3 rounded-lg border border-border p-3 text-left hover:border-primary/30 hover:bg-muted"><div className="rounded-lg bg-muted p-2 text-primary"><Icon size={15} /></div><div className="min-w-0 flex-1"><div className="text-xs font-semibold">{title as string}</div><div className="mt-1 text-[10px] text-muted-foreground">{meta as string}</div></div><ArrowRight size={14} className="text-muted-foreground" /></button>)}</div></div><div className="rounded-xl bg-primary p-5 text-primary-foreground"><div className="flex items-center gap-2 text-secondary"><Sparkles size={16} /><span className="font-mono text-[10px] uppercase tracking-wider">Research note</span></div><p className="mt-3 font-display text-lg leading-snug">Good reports make the next decision easier, not just the last one more presentable.</p></div></div></div></>; }

function Support() { const submit = useSubmitFeedback(); const [sent, setSent] = useState(false); const [form, setForm] = useState({ subject: '', message: '', category: 'Data quality' }); const onSubmit = (e: React.FormEvent) => { e.preventDefault(); submit.mutate({ data: form }, { onSuccess: () => { setSent(true); setForm({ subject: '', message: '', category: 'Data quality' }); } }); }; return <><PageIntro eyebrow="Support / public feedback" title="Help us make this useful." description="Found a gap, a confusing record or a better way to explain a scheme? Send it to the team." /><div className="grid gap-5 lg:grid-cols-[1fr_320px]"><form onSubmit={onSubmit} className="rounded-xl border border-border bg-card p-5 sm:p-7"><div className="grid gap-4 sm:grid-cols-2"><label className="text-xs font-semibold sm:col-span-2">Subject<input data-testid="input-feedback-subject" required value={form.subject} onChange={(e) => setForm({ ...form, subject: e.target.value })} placeholder="What should we look at?" className="mt-1.5 h-11 w-full rounded-lg border border-border bg-background px-3 text-sm outline-none focus:border-primary" /></label><label className="text-xs font-semibold">Category<select data-testid="select-feedback-category" value={form.category} onChange={(e) => setForm({ ...form, category: e.target.value })} className="mt-1.5 h-11 w-full rounded-lg border border-border bg-background px-3 text-sm"><option>Data quality</option><option>Missing scheme</option><option>Product feedback</option><option>Access issue</option></select></label><div className="hidden sm:block" /><label className="text-xs font-semibold sm:col-span-2">Message<textarea data-testid="textarea-feedback-message" required rows={7} value={form.message} onChange={(e) => setForm({ ...form, message: e.target.value })} placeholder="Include the record name, link or context that will help us investigate." className="mt-1.5 w-full resize-y rounded-lg border border-border bg-background p-3 text-sm outline-none focus:border-primary" /></label></div>{sent && <div className="mt-4 flex items-center gap-2 rounded-lg bg-accent/10 p-3 text-xs text-accent"><Check size={15} /> Thanks — your note is in the support queue.</div>}<button data-testid="button-submit-feedback" disabled={submit.isPending} className="mt-5 inline-flex items-center gap-2 rounded-lg bg-primary px-5 py-2.5 text-sm font-semibold text-primary-foreground disabled:opacity-60">{submit.isPending ? <Loader2 size={15} className="animate-spin" /> : <Send size={15} />}Send feedback</button></form><aside className="space-y-4"><div className="rounded-xl border border-border bg-card p-5"><div className="flex h-9 w-9 items-center justify-center rounded-lg bg-secondary/20 text-primary"><CircleHelp size={18} /></div><h2 className="mt-4 font-display text-xl font-semibold">Before you write</h2><div className="mt-3 space-y-3 text-xs leading-relaxed text-muted-foreground"><p>For application decisions, always confirm details with the official department.</p><p>Include the exact title of a record when reporting a correction.</p><p>We review feedback during working hours and publish data fixes transparently.</p></div></div><div className="rounded-xl border border-border bg-muted/40 p-5"><div className="font-mono text-[10px] uppercase tracking-wider text-muted-foreground">Typical response</div><div className="mt-2 font-display text-2xl font-semibold">1–2 days</div><div className="mt-1 text-xs text-muted-foreground">For record and access questions</div></div></aside></div></>; }

function SettingsPage() { const { user } = useUser(); const [saved, setSaved] = useState(false); const [prefs, setPrefs] = useState({ email: true, status: true, digest: false }); const displayName = user?.fullName ?? user?.firstName ?? 'Researcher'; const email = user?.primaryEmailAddress?.emailAddress ?? ''; return <><PageIntro eyebrow="Account / preferences" title="Make the workspace yours." description="Keep your public profile, working role and update preferences current." action={saved ? <span className="flex items-center gap-2 text-xs font-semibold text-accent"><Check size={15} /> Saved just now</span> : undefined} /><div className="grid gap-5 lg:grid-cols-[1fr_340px]"><div className="space-y-5"><section className="rounded-xl border border-border bg-card p-5 sm:p-7"><div className="mb-5 flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-full bg-primary text-xs font-bold text-primary-foreground">{displayName.slice(0, 2).toUpperCase()}</div><div><h2 className="font-display text-xl font-semibold">Profile</h2><p className="text-xs text-muted-foreground">How your work appears across PolicyGPT</p></div></div><div className="grid gap-4 sm:grid-cols-2"><label className="text-xs font-semibold">Full name<input data-testid="input-settings-name" defaultValue={displayName} className="mt-1.5 h-10 w-full rounded-lg border border-border bg-background px-3 text-sm" /></label><label className="text-xs font-semibold">Email address<input data-testid="input-settings-email" defaultValue={email} readOnly className="mt-1.5 h-10 w-full rounded-lg border border-border bg-background px-3 text-sm" /></label><label className="text-xs font-semibold">Working role<select data-testid="select-settings-role" defaultValue="Citizen researcher" className="mt-1.5 h-10 w-full rounded-lg border border-border bg-background px-3 text-sm"><option>Citizen researcher</option><option>Government official</option><option>Academic researcher</option><option>Organisation</option></select></label><label className="text-xs font-semibold">Primary location<select data-testid="select-settings-location" defaultValue="Maharashtra" className="mt-1.5 h-10 w-full rounded-lg border border-border bg-background px-3 text-sm"><option>Maharashtra</option><option>Rajasthan</option><option>Bihar</option><option>Delhi</option></select></label></div></section><section className="rounded-xl border border-border bg-card p-5 sm:p-7"><div className="flex items-center justify-between"><div><h2 className="font-display text-xl font-semibold">Notifications</h2><p className="mt-1 text-xs text-muted-foreground">Choose what earns a place in your attention queue.</p></div><Bell size={18} className="text-primary" /></div><div className="mt-5 divide-y divide-border">{[['email', 'Weekly intelligence digest', 'A compact read of new records and changes.'], ['status', 'Saved record changes', 'When a policy or scheme you follow changes.'], ['digest', 'Research tips', 'Occasional notes on getting more from the workspace.']].map(([key, title, desc]) => <label key={key} className="flex cursor-pointer items-center justify-between gap-4 py-4 first:pt-0 last:pb-0"><div><div className="text-sm font-semibold">{title}</div><div className="mt-1 text-xs text-muted-foreground">{desc}</div></div><input data-testid={`toggle-settings-${key}`} type="checkbox" checked={(prefs as any)[key]} onChange={(e) => setPrefs({ ...prefs, [key]: e.target.checked })} className="h-4 w-4 accent-[hsl(var(--primary))]" /></label>)}</div></section><button data-testid="button-save-settings" onClick={() => setSaved(true)} className="rounded-lg bg-primary px-5 py-2.5 text-sm font-semibold text-primary-foreground">Save preferences</button></div><aside className="space-y-4"><div className="rounded-xl border border-border bg-card p-5"><div className="flex items-center gap-2 text-primary"><UserRound size={17} /><span className="font-mono text-[10px] uppercase tracking-wider">Current role</span></div><div className="mt-3 font-display text-2xl font-semibold">Citizen researcher</div><p className="mt-2 text-xs leading-relaxed text-muted-foreground">Your role tunes the language, context and shortcuts you see in the workspace.</p><button data-testid="button-change-role" className="mt-4 text-xs font-semibold text-primary hover:underline">Change role</button></div><div className="rounded-xl border border-border bg-muted/40 p-5"><div className="flex items-center gap-2 text-muted-foreground"><Moon size={16} /><span className="font-mono text-[10px] uppercase tracking-wider">Appearance</span></div><p className="mt-3 text-xs text-muted-foreground">PolicyGPT uses a warm civic light theme for clear reading in long sessions.</p></div></aside></div></>; }

function Router() { return <Switch><Route path="/" component={Overview} /><Route path="/policies" component={Policies} /><Route path="/policies/:id" component={PolicyDetail} /><Route path="/schemes" component={Schemes} /><Route path="/schemes/:id" component={SchemeDetail} /><Route path="/eligibility" component={Eligibility} /><Route path="/compare" component={Compare} /><Route path="/notifications" component={Notifications} /><Route path="/reports" component={Reports} /><Route path="/support" component={Support} /><Route path="/settings" component={SettingsPage} /><Route component={NotFound} /></Switch>; }
function RoutedErrorBoundary({ children }: { children: React.ReactNode }) { const [location] = useLocation(); return <ErrorBoundary resetKey={location}>{children}</ErrorBoundary>; }
function Landing() {
  return <div className="min-h-[100dvh] bg-background text-foreground">
    <header className="mx-auto flex max-w-6xl items-center justify-between px-5 py-6 sm:px-8">
      <Link href="/" className="flex items-center gap-3">
        <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-secondary text-primary"><Shield size={20} /></div>
        <div><div className="font-display text-lg font-semibold">Policy<span className="text-secondary">GPT</span></div><div className="font-mono text-[9px] uppercase tracking-[.18em] text-muted-foreground">public intelligence</div></div>
      </Link>
      <div className="flex items-center gap-2"><Link href="/sign-in" className="rounded-lg px-3 py-2 text-sm font-semibold text-muted-foreground hover:bg-muted hover:text-foreground">Sign in</Link><Link href="/sign-up" className="rounded-lg bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground shadow-sm hover:-translate-y-0.5">Create account</Link></div>
    </header>
    <main className="mx-auto grid max-w-6xl gap-12 px-5 pb-20 pt-12 sm:px-8 lg:grid-cols-[1.1fr_.9fr] lg:items-center lg:pt-24">
      <section><div className="mb-4 inline-flex items-center gap-2 rounded-full border border-accent/20 bg-accent/8 px-3 py-1.5 font-mono text-[10px] uppercase tracking-[.16em] text-accent"><span className="h-1.5 w-1.5 rounded-full bg-accent" />Evidence-led public policy search</div><h1 className="max-w-3xl font-display text-5xl font-semibold tracking-[-.055em] sm:text-7xl">Understand the decisions that shape public life.</h1><p className="mt-6 max-w-xl text-base leading-8 text-muted-foreground sm:text-lg">PolicyGPT brings policies, public schemes, eligibility signals and source context into one clear workspace for citizens, researchers and public teams.</p><div className="mt-8 flex flex-wrap gap-3"><Link href="/sign-up" className="inline-flex items-center gap-2 rounded-lg bg-primary px-5 py-3 text-sm font-semibold text-primary-foreground shadow-sm hover:-translate-y-0.5">Start researching <ArrowRight size={16} /></Link><Link href="/sign-in" className="inline-flex items-center gap-2 rounded-lg border border-border px-5 py-3 text-sm font-semibold hover:bg-muted">Sign in to workspace</Link></div></section>
      <section className="dot-grid rounded-2xl border border-primary/10 bg-primary/5 p-5 sm:p-7"><div className="rounded-xl border border-border bg-card p-5 shadow-[0_12px_40px_hsl(var(--primary)/.08)]"><div className="flex items-center justify-between border-b border-border pb-4"><div><div className="font-mono text-[9px] uppercase tracking-[.16em] text-muted-foreground">PolicyGPT / live index</div><div className="mt-1 font-display text-xl font-semibold">A clearer starting point</div></div><Shield size={20} className="text-accent" /></div><div className="mt-5 space-y-3">{[['1,248', 'policies indexed'], ['386', 'public schemes'], ['12', 'active alerts']].map(([value, label]) => <div key={label} className="flex items-center justify-between rounded-lg bg-muted/60 px-4 py-3"><span className="font-display text-2xl font-semibold">{value}</span><span className="text-xs text-muted-foreground">{label}</span></div>)}</div><div className="mt-5 rounded-lg bg-primary p-4 text-primary-foreground"><div className="flex items-center gap-2 text-secondary"><Sparkles size={15} /><span className="font-mono text-[10px] uppercase tracking-wider">Research mode</span></div><p className="mt-2 text-sm leading-relaxed text-primary-foreground/70">Source trails, status history and practical next steps for every record.</p></div></div></section>
    </main>
  </div>;
}

function SignInPage() {
  return <div className="flex min-h-[100dvh] items-center justify-center bg-background px-4"><SignIn routing="path" path={`${basePath}/sign-in`} signUpUrl={`${basePath}/sign-up`} /></div>;
}

function SignUpPage() {
  return <div className="flex min-h-[100dvh] items-center justify-center bg-background px-4"><SignUp routing="path" path={`${basePath}/sign-up`} signInUrl={`${basePath}/sign-in`} /></div>;
}

function ProtectedApp() {
  return <Shell><RoutedErrorBoundary><Router /></RoutedErrorBoundary></Shell>;
}

function PortalGate() {
  return <><Show when="signed-in"><ProtectedApp /></Show><Show when="signed-out"><Landing /></Show></>;
}

function ClerkQueryClientCacheInvalidator() {
  const { addListener } = useClerk();
  const client = useQueryClient();
  const previousUserId = useRef<string | null | undefined>(undefined);
  useEffect(() => {
    const unsubscribe = addListener(({ user }) => {
      const nextUserId = user?.id ?? null;
      if (previousUserId.current !== undefined && previousUserId.current !== nextUserId) client.clear();
      previousUserId.current = nextUserId;
    });
    return unsubscribe;
  }, [addListener, client]);
  return null;
}

function ClerkProviderWithRoutes() {
  const [, setLocation] = useLocation();
  return <ClerkProvider publishableKey={clerkPubKey} proxyUrl={clerkProxyUrl} appearance={clerkAppearance} signInUrl={`${basePath}/sign-in`} signUpUrl={`${basePath}/sign-up`} localization={{ signIn: { start: { title: 'Welcome back', subtitle: 'Sign in to continue to PolicyGPT' } }, signUp: { start: { title: 'Create your PolicyGPT account', subtitle: 'Start building a clearer view of public policy' } } }} routerPush={(to) => setLocation(stripBase(to))} routerReplace={(to) => setLocation(stripBase(to), { replace: true })}>
    <ClerkQueryClientCacheInvalidator />
    <Switch><Route path="/sign-in/*?" component={SignInPage} /><Route path="/sign-up/*?" component={SignUpPage} /><Route component={PortalGate} /></Switch>
  </ClerkProvider>;
}

function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={basePath}><ClerkProviderWithRoutes /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>; }
export default App;